package postgres

import (
	"context"
	"errors"
	"fmt"

	"github.com/jackc/pgx/v5/pgconn"
)

const maxLabelCodeAttempts = 5

var errNoRow = errors.New("no row")

// resetLabelCode gives the row a new label code generated by the database (new_label_code),
// retrying in the practically impossible case that it clashes with an existing one. It returns
// errNoRow when the row does not exist. table and prefix are constants chosen by the callers.
func resetLabelCode(ctx context.Context, db execer, table, prefix, id string) error {
	query := fmt.Sprintf("UPDATE %s SET label_code = new_label_code('%s') WHERE id = $1", table, prefix)
	for attempt := 0; attempt < maxLabelCodeAttempts; attempt++ {
		tag, err := db.Exec(ctx, query, id)
		var pgErr *pgconn.PgError
		if errors.As(err, &pgErr) && pgErr.Code == pgUniqueViolation {
			continue
		}
		if err != nil {
			return fmt.Errorf("reset label code: %w", err)
		}
		if tag.RowsAffected() == 0 {
			return errNoRow
		}
		return nil
	}
	return errors.New("reset label code: could not find an unused code")
}
